472	    private ResultActions recover(String bagTag, String missingLegId, String actualStation) throws Exception {
473	        return postJson("/api/bags/recover", Map.of(
474	                "requestId", UUID.randomUUID().toString(),
475	                "bagTag", bagTag, "missingLegId", missingLegId, "actualStation", actualStation));
476	    }
477	
478	    private ResultActions postJson(String url, Object body) throws Exception {
479	        return mockMvc.perform(post(url)
480	                .contentType(MediaType.APPLICATION_JSON)
481	                .content(objectMapper.writeValueAsString(body)));
482	    }
483	
484	    /** 同步起跑并发执行任务，结果按提交顺序返回（异常包装为返回值）。 */
485	    private List<Object> runConcurrently(List<Callable<Object>> tasks) throws Exception {
486	        CountDownLatch ready = new CountDownLatch(tasks.size());
487	        CountDownLatch start = new CountDownLatch(1);
488	        List<Future<Object>> futures = new ArrayList<>();
489	        for (Callable<Object> task : tasks) {
490	            futures.add(executor.submit(() -> {
491	                ready.countDown();
492	                assertThat(start.await(10, TimeUnit.SECONDS)).isTrue();
493	                try {
494	                    return task.call();
495	                } catch (ApiException ex) {
496	                    return ex;
497	                }
498	            }));
499	        }
500	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
501	        start.countDown();
502	        List<Object> results = new ArrayList<>();
503	        for (Future<Object> future : futures) {
504	            results.add(future.get(30, TimeUnit.SECONDS));
505	        }
506	        return results;
507	    }
