                missingLeg.manifestLeafCount(), request.proof(),
                MerkleTree.unhex(missingLeg.manifestRoot()));
    } catch (IllegalArgumentException ex) {
        valid = false;
    }
    if (!valid) {
        throw ApiException.unprocessable("成员证明核验失败: 路径长度、方向或袋号不符");
    }
}

